/**
 * Error type crossing the UniFFI boundary from `DocumentCore`.
 */
sealed class DocumentCoreException: kotlin.Exception() {
    
    class ConfigurationException(
        
        val `details`: kotlin.String
        ) : DocumentCoreException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    class FileBrokerFailure(
        
        val `details`: kotlin.String
        ) : DocumentCoreException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    class PasswordRequired(
        ) : DocumentCoreException() {
        override val message
            get() = ""
    }
    
    class InvalidPdf(
        
        val `details`: kotlin.String
        ) : DocumentCoreException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    class SessionNotFound(
        
        val `sessionId`: kotlin.String
        ) : DocumentCoreException() {
        override val message
            get() = "sessionId=${ `sessionId` }"
    }
    
    class NavigationFailure(
        
        val `details`: kotlin.String
        ) : DocumentCoreException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    class TransactionFailure(
        
        val `details`: kotlin.String
        ) : DocumentCoreException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    class InternalFailure(
        
        val `details`: kotlin.String
        ) : DocumentCoreException() {
        override val message
            get() = "details=${ `details` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<DocumentCoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): DocumentCoreException = FfiConverterTypeDocumentCoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeDocumentCoreError : FfiConverterRustBuffer<DocumentCoreException> {
    override fun read(buf: ByteBuffer): DocumentCoreException {
        

        return when(buf.getInt()) {
            1 -> DocumentCoreException.ConfigurationException(
                FfiConverterString.read(buf),
                )
            2 -> DocumentCoreException.FileBrokerFailure(
                FfiConverterString.read(buf),
                )
            3 -> DocumentCoreException.PasswordRequired()
            4 -> DocumentCoreException.InvalidPdf(
                FfiConverterString.read(buf),
                )
            5 -> DocumentCoreException.SessionNotFound(
                FfiConverterString.read(buf),
                )
            6 -> DocumentCoreException.NavigationFailure(
                FfiConverterString.read(buf),
                )
            7 -> DocumentCoreException.TransactionFailure(
                FfiConverterString.read(buf),
                )
            8 -> DocumentCoreException.InternalFailure(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: DocumentCoreException): ULong {
        return when(value) {
            is DocumentCoreException.ConfigurationException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`details`)
            )
            is DocumentCoreException.FileBrokerFailure -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`details`)
            )
            is DocumentCoreException.PasswordRequired -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is DocumentCoreException.InvalidPdf -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`details`)
            )
            is DocumentCoreException.SessionNotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`sessionId`)
            )
            is DocumentCoreException.NavigationFailure -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`details`)
            )
            is DocumentCoreException.TransactionFailure -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`details`)
            )
            is DocumentCoreException.InternalFailure -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`details`)
            )
        }
    }

    override fun write(value: DocumentCoreException, buf: ByteBuffer) {
        when(value) {
            is DocumentCoreException.ConfigurationException -> {
                buf.putInt(1)
                FfiConverterString.write(value.`details`, buf)
                Unit
            }
            is DocumentCoreException.FileBrokerFailure -> {
                buf.putInt(2)
                FfiConverterString.write(value.`details`, buf)
                Unit
            }
            is DocumentCoreException.PasswordRequired -> {
                buf.putInt(3)
                Unit
            }
            is DocumentCoreException.InvalidPdf -> {
                buf.putInt(4)
                FfiConverterString.write(value.`details`, buf)
                Unit
            }
            is DocumentCoreException.SessionNotFound -> {
                buf.putInt(5)
                FfiConverterString.write(value.`sessionId`, buf)
                Unit
            }
            is DocumentCoreException.NavigationFailure -> {
                buf.putInt(6)
                FfiConverterString.write(value.`details`, buf)
                Unit
            }
            is DocumentCoreException.TransactionFailure -> {
                buf.putInt(7)
                FfiConverterString.write(value.`details`, buf)
                Unit
            }
            is DocumentCoreException.InternalFailure -> {
                buf.putInt(8)
                FfiConverterString.write(value.`details`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



